import { test, expect } from '@playwright/test';

test.describe('User Authentication', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
  });

  test('should log in with email', async ({ page }) => {
    await page.getByLabel('Email or Username').fill('user@example.com');
    await page.getByLabel('Password').fill('password123');
    await page.getByRole('button', { name: 'Log In' }).click();
    await expect(page.getByText('Welcome back!')).toBeVisible();
  });

  test('should log in with username', async ({ page }) => {
    await page.getByLabel('Email or Username').fill('username123');
    await page.getByLabel('Password').fill('password123');
    await page.getByRole('button', { name: 'Log In' }).click();
    await expect(page.getByText('Welcome back!')).toBeVisible();
  });
});
